import{_ as s,c as a,b as p,o as t}from"./app-CyxyZJrS.js";const e={};function l(o,n){return t(),a("div",null,[...n[0]||(n[0]=[p(`<h1 id="_1磐松资产-前端实习-一面" tabindex="-1"><a class="header-anchor" href="#_1磐松资产-前端实习-一面"><span>1磐松资产-前端实习-一面</span></a></h1><p>&gt; Last Format Time：6/12/2026 21:03:57</p><h2 id="一面" tabindex="-1"><a class="header-anchor" href="#一面"><span>一面</span></a></h2><p>时间：一面11.21.25 时长：30min</p><h3 id="考试信息" tabindex="-1"><a class="header-anchor" href="#考试信息"><span>考试信息</span></a></h3><p>使用ShowMeBug这平台来考，双机位的摄像头监考，考的东西不太难，但是我有点忘了。大题的最后一道编程题，那个系统不太会用，浪费了不少时间。</p><h3 id="考试内容-一共17道" tabindex="-1"><a class="header-anchor" href="#考试内容-一共17道"><span>考试内容（一共17道）</span></a></h3><p>有点忘了</p><h5 id="选择" tabindex="-1"><a class="header-anchor" href="#选择"><span>选择</span></a></h5><ul><li><ol><li>reduce，累加的用法</li></ol></li><li><ol start="2"><li>对象的字面量创建</li></ol></li><li><ol start="3"><li>Array.from的用法，它能做什么</li></ol></li><li><ol start="4"><li>将一个数组转化为使用逗号分隔的字符串</li></ol></li><li><ol start="5"><li>如何为对象添加一个方法</li></ol></li></ul><h5 id="填空" tabindex="-1"><a class="header-anchor" href="#填空"><span>填空</span></a></h5><ul><li><ol><li>初始化一个空对象的方法</li></ol></li><li><ol start="2"><li>连接字符串的符号</li></ol></li><li><ol start="3"><li>忘了</li></ol></li></ul><h5 id="大题-三道" tabindex="-1"><a class="header-anchor" href="#大题-三道"><span>大题（三道）</span></a></h5><ul><li><ol><li>分析事件循环机制</li></ol></li><li><ol start="2"><li>编程，点击背景将一个三角形的颜色由红转换为粉色</li></ol></li></ul><h3 id="参考答案" tabindex="-1"><a class="header-anchor" href="#参考答案"><span>参考答案</span></a></h3><p>以下是前端笔试题目对应的参考答案，兼顾基础知识点准确性和实际应用场景，符合面试笔试答题规范：</p><h3 id="选择题-含解析" tabindex="-1"><a class="header-anchor" href="#选择题-含解析"><span>选择题（含解析）</span></a></h3><h5 id="reduce-累加的用法" tabindex="-1"><a class="header-anchor" href="#reduce-累加的用法"><span>reduce 累加的用法</span></a></h5><h5 id="答案" tabindex="-1"><a class="header-anchor" href="#答案"><span>答案</span></a></h5><p><code>reduce</code> 是数组方法，用于对数组元素逐个处理并累加得到最终结果，核心语法：<code>arr.reduce((acc, curr, idx, arr) =&amp;gt; {}, initialValue)</code></p><ul><li><p>关键参数：</p><ul><li>回调函数：接收4个参数（<code>acc</code> 累计值、<code>curr</code> 当前元素、<code>idx</code> 当前索引、<code>arr</code> 原数组）</li><li><code>initialValue</code>（可选）：累计值初始值，不传递则默认以数组第1个元素为初始 <code>acc</code></li></ul></li><li><p>示例（数组求和）：</p></li></ul><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> arr <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> sum <span class="token operator">=</span> arr<span class="token punctuation">.</span><span class="token function">reduce</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">acc<span class="token punctuation">,</span> curr</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> acc <span class="token operator">+</span> curr<span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 结果：6</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h5 id="对象的字面量创建" tabindex="-1"><a class="header-anchor" href="#对象的字面量创建"><span>对象的字面量创建</span></a></h5><h5 id="答案-1" tabindex="-1"><a class="header-anchor" href="#答案-1"><span>答案</span></a></h5><p>使用 <code>{}</code> 直接定义对象属性和方法（ES6+ 支持简洁语法），示例：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 基础字面量创建</span></span>
<span class="line"><span class="token keyword">const</span> person <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token literal-property property">name</span><span class="token operator">:</span> <span class="token string">&quot;张三&quot;</span><span class="token punctuation">,</span> <span class="token comment">// 属性键值对</span></span>
<span class="line">  <span class="token literal-property property">age</span><span class="token operator">:</span> <span class="token number">20</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token function-variable function">sayHi</span><span class="token operator">:</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token comment">// 方法</span></span>
<span class="line">    console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">Hi, </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span><span class="token keyword">this</span><span class="token punctuation">.</span>name<span class="token interpolation-punctuation punctuation">}</span></span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// ES6 简洁语法（方法简写、属性简写）</span></span>
<span class="line"><span class="token keyword">const</span> name <span class="token operator">=</span> <span class="token string">&quot;李四&quot;</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> student <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">  name<span class="token punctuation">,</span> <span class="token comment">// 属性简写（键名与变量名一致）</span></span>
<span class="line">  <span class="token function">study</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token comment">// 方法简写（省略 function）</span></span>
<span class="line">    console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;学习中&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h5 id="array-from-的用法" tabindex="-1"><a class="header-anchor" href="#array-from-的用法"><span>Array.from 的用法</span></a></h5><h5 id="答案-2" tabindex="-1"><a class="header-anchor" href="#答案-2"><span>答案</span></a></h5><p>将「类数组对象」或「可迭代对象（Iterable）」转为真正的数组，支持映射和绑定this，语法：<code>Array.from(arrayLike, mapFn?, thisArg?)</code></p><ul><li>核心功能： <ul><li><ol><li>转换类数组（含 <code>length</code> 属性的对象，如 <code>arguments</code>、DOM 集合）</li></ol></li><li><ol start="2"><li>转换可迭代对象（字符串、Set、Map 等）</li></ol></li><li><ol start="3"><li>第二个参数（可选）：映射函数（类似 <code>map</code>）</li></ol></li></ul></li><li>示例：</li></ul><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 转换 DOM 集合</span></span>
<span class="line"><span class="token keyword">const</span> divs <span class="token operator">=</span> document<span class="token punctuation">.</span><span class="token function">querySelectorAll</span><span class="token punctuation">(</span><span class="token string">&quot;div&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> divArr <span class="token operator">=</span> Array<span class="token punctuation">.</span><span class="token function">from</span><span class="token punctuation">(</span>divs<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 转为数组</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 转换字符串（每个字符为数组元素）</span></span>
<span class="line">Array<span class="token punctuation">.</span><span class="token function">from</span><span class="token punctuation">(</span><span class="token string">&quot;abc&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// [&#39;a&#39;, &#39;b&#39;, &#39;c&#39;]</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 带映射函数（数组去重+平方）</span></span>
<span class="line"><span class="token keyword">const</span> set <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Set</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">Array<span class="token punctuation">.</span><span class="token function">from</span><span class="token punctuation">(</span>set<span class="token punctuation">,</span> <span class="token parameter">x</span> <span class="token operator">=&gt;</span> x <span class="token operator">*</span> x<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// [1, 4, 9]</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h5 id="将数组转化为逗号分隔的字符串" tabindex="-1"><a class="header-anchor" href="#将数组转化为逗号分隔的字符串"><span>将数组转化为逗号分隔的字符串</span></a></h5><h5 id="答案-3" tabindex="-1"><a class="header-anchor" href="#答案-3"><span>答案</span></a></h5><p>使用数组方法 <code>join(&#39;,&#39;)</code>（最简洁高效），示例：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> arr <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string">&quot;苹果&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;香蕉&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;橙子&quot;</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> str <span class="token operator">=</span> arr<span class="token punctuation">.</span><span class="token function">join</span><span class="token punctuation">(</span><span class="token string">&#39;,&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 结果：&quot;苹果,香蕉,橙子&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 特殊情况：空数组返回空串</span></span>
<span class="line"><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">.</span><span class="token function">join</span><span class="token punctuation">(</span><span class="token string">&#39;,&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// &quot;&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h5 id="为对象添加一个方法" tabindex="-1"><a class="header-anchor" href="#为对象添加一个方法"><span>为对象添加一个方法</span></a></h5><h5 id="答案-4" tabindex="-1"><a class="header-anchor" href="#答案-4"><span>答案</span></a></h5><p>3种常用方式，优先推荐ES6简洁语法：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> obj <span class="token operator">=</span> <span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 方式1：字面量创建时直接定义（初始化阶段）</span></span>
<span class="line"><span class="token keyword">const</span> obj1 <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token function">eat</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;吃饭&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span> <span class="token comment">// ES6 方法简写</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 方式2：后期通过点语法/方括号添加（动态添加）</span></span>
<span class="line">obj2<span class="token punctuation">.</span><span class="token function-variable function">say</span> <span class="token operator">=</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;说话&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line">obj2<span class="token punctuation">[</span><span class="token string">&quot;run&quot;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;跑步&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 方括号支持动态键名</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 方式3：通过 Object.assign 批量添加</span></span>
<span class="line">Object<span class="token punctuation">.</span><span class="token function">assign</span><span class="token punctuation">(</span>obj3<span class="token punctuation">,</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token function">jump</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;跳跃&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="填空题-含核心答案" tabindex="-1"><a class="header-anchor" href="#填空题-含核心答案"><span>填空题（含核心答案）</span></a></h3><h5 id="初始化一个空对象的方法" tabindex="-1"><a class="header-anchor" href="#初始化一个空对象的方法"><span>初始化一个空对象的方法</span></a></h5><h5 id="答案-至少2种常用方式" tabindex="-1"><a class="header-anchor" href="#答案-至少2种常用方式"><span>答案（至少2种常用方式）</span></a></h5><ul><li><code>const obj = {};</code>（最简洁，推荐）</li><li><code>const obj = new Object();</code>（构造函数方式）</li><li><code>const obj = Object.create({});</code>（创建原型为指定对象的空对象）</li><li><code>const obj = Object.create(null);</code>（创建无原型的空对象）</li></ul><h5 id="连接字符串的符号" tabindex="-1"><a class="header-anchor" href="#连接字符串的符号"><span>连接字符串的符号</span></a></h5><h5 id="答案-5" tabindex="-1"><a class="header-anchor" href="#答案-5"><span>答案</span></a></h5><ul><li><code>+</code> 运算符（基础用法）：<code>&quot;a&quot; + &quot;b&quot; + 123</code> → <code>&quot;ab123&quot;</code></li><li>模板字符串 <code>\`</code>（ES6 推荐，支持换行和变量）：<code>const name = &quot;张三&quot;; \`你好，\${name}\`</code></li></ul><h3 id="大题-详细解析-代码" tabindex="-1"><a class="header-anchor" href="#大题-详细解析-代码"><span>大题（详细解析+代码）</span></a></h3><h5 id="事件循环机制-event-loop-分析" tabindex="-1"><a class="header-anchor" href="#事件循环机制-event-loop-分析"><span>事件循环机制（Event Loop）分析</span></a></h5><h5 id="核心结论" tabindex="-1"><a class="header-anchor" href="#核心结论"><span>核心结论</span></a></h5><p>JS 是单线程语言，事件循环是解决「异步任务执行顺序」的核心机制，分为「浏览器环境」和「Node 环境」，前端重点关注浏览器环境。</p><h5 id="浏览器环境事件循环流程" tabindex="-1"><a class="header-anchor" href="#浏览器环境事件循环流程"><span>浏览器环境事件循环流程：</span></a></h5><ol><li><strong>执行栈（Call Stack）</strong>：同步代码按顺序进入执行栈，执行完后出栈；</li><li><strong>异步任务分类</strong>： <ul><li>微任务（Microtasks）：优先级高，执行栈空后立即执行所有微任务（队列清空才会执行宏任务） <ul><li>常见：<code>Promise.then/catch/finally</code>、<code>queueMicrotask()</code>、<code>process.nextTick</code>（Node 特有）</li></ul></li><li>宏任务（Macrotasks）：优先级低，微任务执行完后执行1个宏任务（然后回到微任务检查） <ul><li>常见：<code>setTimeout/setInterval</code>、DOM 事件（如 click）、AJAX 请求、<code>requestAnimationFrame</code></li></ul></li></ul></li><li><strong>循环逻辑</strong>： <ul><li>执行所有同步代码 → 执行栈空 → 执行所有微任务 → 取1个宏任务执行 → 执行栈空 → 重复上述步骤</li></ul></li></ol><h5 id="示例代码分析-理解执行顺序" tabindex="-1"><a class="header-anchor" href="#示例代码分析-理解执行顺序"><span>示例代码分析（理解执行顺序）：</span></a></h5><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;1&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 同步代码</span></span>
<span class="line"><span class="token function">setTimeout</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;2&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 宏任务</span></span>
<span class="line">Promise<span class="token punctuation">.</span><span class="token function">resolve</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;3&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 微任务</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;4&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 同步代码</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 执行顺序：1 → 4 → 3 → 2</span></span>
<span class="line"><span class="token comment">// 解析：</span></span>
<span class="line"><span class="token comment">// 1. 同步代码 &quot;1&quot;、&quot;4&quot; 先执行，输出 1、4；</span></span>
<span class="line"><span class="token comment">// 2. 执行栈空，执行微任务 Promise.then，输出 3；</span></span>
<span class="line"><span class="token comment">// 3. 微任务队列清空，执行1个宏任务 setTimeout，输出 2。</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h5 id="编程题-点击背景切换三角形颜色-红→粉" tabindex="-1"><a class="header-anchor" href="#编程题-点击背景切换三角形颜色-红→粉"><span>编程题：点击背景切换三角形颜色（红→粉）</span></a></h5><h5 id="需求" tabindex="-1"><a class="header-anchor" href="#需求"><span>需求</span></a></h5><p>页面背景可点击，点击后将三角形由红色转为粉色（再次点击可切换回红色，可选优化）。</p><h5 id="实现思路" tabindex="-1"><a class="header-anchor" href="#实现思路"><span>实现思路</span></a></h5><ul><li>HTML：创建背景容器和三角形元素；</li><li>CSS：用 <code>border</code> 实现三角形（宽高为0，单边设颜色，其他透明），初始红色；</li><li>JS：给背景容器绑定点击事件，切换三角形的颜色（用 <code>classList.toggle</code> 或直接修改 <code>style</code>）。</li></ul><h5 id="完整代码-可直接运行" tabindex="-1"><a class="header-anchor" href="#完整代码-可直接运行"><span>完整代码（可直接运行）</span></a></h5><div class="language-html line-numbers-mode" data-highlighter="prismjs" data-ext="html"><pre><code class="language-html"><span class="line"><span class="token doctype"><span class="token punctuation">&lt;!</span><span class="token doctype-tag">DOCTYPE</span> <span class="token name">html</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span> <span class="token attr-name">lang</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>zh-CN<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span></span>
<span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>head</span><span class="token punctuation">&gt;</span></span></span>
<span class="line">  <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>meta</span> <span class="token attr-name">charset</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>UTF-8<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span></span>
<span class="line">  <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>title</span><span class="token punctuation">&gt;</span></span>三角形颜色切换<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>title</span><span class="token punctuation">&gt;</span></span></span>
<span class="line">  <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>style</span><span class="token punctuation">&gt;</span></span><span class="token style"><span class="token language-css"></span>
<span class="line">    <span class="token comment">/* 背景容器：占满屏幕，可点击 */</span></span>
<span class="line">    <span class="token selector">.bg-container</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token property">width</span><span class="token punctuation">:</span> 100vw<span class="token punctuation">;</span></span>
<span class="line">      <span class="token property">height</span><span class="token punctuation">:</span> 100vh<span class="token punctuation">;</span></span>
<span class="line">      <span class="token property">background-color</span><span class="token punctuation">:</span> #f5f5f5<span class="token punctuation">;</span></span>
<span class="line">      <span class="token property">display</span><span class="token punctuation">:</span> flex<span class="token punctuation">;</span></span>
<span class="line">      <span class="token property">justify-content</span><span class="token punctuation">:</span> center<span class="token punctuation">;</span></span>
<span class="line">      <span class="token property">align-items</span><span class="token punctuation">:</span> center<span class="token punctuation">;</span></span>
<span class="line">      <span class="token property">cursor</span><span class="token punctuation">:</span> pointer<span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    <span class="token comment">/* 三角形：用 border 实现 */</span></span>
<span class="line">    <span class="token selector">.triangle</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token property">width</span><span class="token punctuation">:</span> 0<span class="token punctuation">;</span></span>
<span class="line">      <span class="token property">height</span><span class="token punctuation">:</span> 0<span class="token punctuation">;</span></span>
<span class="line">      <span class="token comment">/* 初始红色：下三角（border-bottom 设颜色，其他透明） */</span></span>
<span class="line">      <span class="token property">border-left</span><span class="token punctuation">:</span> 50px solid transparent<span class="token punctuation">;</span></span>
<span class="line">      <span class="token property">border-right</span><span class="token punctuation">:</span> 50px solid transparent<span class="token punctuation">;</span></span>
<span class="line">      <span class="token property">border-bottom</span><span class="token punctuation">:</span> 100px solid red<span class="token punctuation">;</span> <span class="token comment">/* 红色初始值 */</span></span>
<span class="line">      <span class="token property">transition</span><span class="token punctuation">:</span> border-color 0.3s ease<span class="token punctuation">;</span> <span class="token comment">/* 过渡动画，优化体验 */</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    <span class="token comment">/* 粉色状态类 */</span></span>
<span class="line">    <span class="token selector">.triangle.pink</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token property">border-bottom-color</span><span class="token punctuation">:</span> pink<span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">  </span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>style</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>head</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span></span>
<span class="line">  <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>bg-container<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span></span>
<span class="line">    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>triangle<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span></span>
<span class="line">  <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span></span>
<span class="line">  <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>script</span><span class="token punctuation">&gt;</span></span><span class="token script"><span class="token language-javascript"></span>
<span class="line">    <span class="token comment">// 1. 获取 DOM 元素</span></span>
<span class="line">    <span class="token keyword">const</span> bgContainer <span class="token operator">=</span> document<span class="token punctuation">.</span><span class="token function">querySelector</span><span class="token punctuation">(</span><span class="token string">&#39;.bg-container&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">const</span> triangle <span class="token operator">=</span> document<span class="token punctuation">.</span><span class="token function">querySelector</span><span class="token punctuation">(</span><span class="token string">&#39;.triangle&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 2. 绑定点击事件</span></span>
<span class="line">    bgContainer<span class="token punctuation">.</span><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;click&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token comment">// 切换 pink 类：有则移除（红），无则添加（粉）</span></span>
<span class="line">      triangle<span class="token punctuation">.</span>classList<span class="token punctuation">.</span><span class="token function">toggle</span><span class="token punctuation">(</span><span class="token string">&#39;pink&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  </span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>script</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>html</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h5 id="代码说明" tabindex="-1"><a class="header-anchor" href="#代码说明"><span>代码说明</span></a></h5><ul><li>三角形实现：通过 <code>border</code> 透明边框叠加，仅底部边框设颜色，形成下三角；</li><li>颜色切换：用 <code>classList.toggle</code> 简化逻辑，点击一次添加 <code>pink</code> 类（粉色），再点击移除（红色）；</li><li>优化点：添加 <code>transition</code> 过渡动画，颜色切换更流畅，提升用户体验。</li></ul><h3 id="复盘反思" tabindex="-1"><a class="header-anchor" href="#复盘反思"><span>复盘反思</span></a></h3><p>考试我个人认为考的不太好，虽然选填的答案应该还可以，但是事件循环机制忘了，最后一道的三角形也没整出来，忘记边框还能这样用了。也没有进行充足的复习（Java快考试了），周一还有个字节的，周五考完试，周末我要好好复习一下，尽最大可能拿下这个（拿不下我还有下家😋😋😋）</p><p>另外笔试题全部都是js的题，尤其是es6的部分特别的多，以及常用的API考的都很多，没考css和html</p><p>&gt;11.22.25 一面过了😋，周三下午二面（应该没有三面了吧）</p><hr><h2 id="二面" tabindex="-1"><a class="header-anchor" href="#二面"><span>二面</span></a></h2><p>时间：11/26/25 时长：46min左右</p><h3 id="流程" tabindex="-1"><a class="header-anchor" href="#流程"><span>流程</span></a></h3><ul><li>自我介绍</li><li>提问</li><li>反问</li></ul><h3 id="提问内容" tabindex="-1"><a class="header-anchor" href="#提问内容"><span>提问内容</span></a></h3><ul><li>数组去重的方法</li><li>promise.allsettled和promise.all的区别❌️ &gt; ⚠️ 纠错：正确写法为 <code>Promise.allSettled</code> 和 <code>Promise.all</code>（首字母大写）</li><li>如何设计一个简单的事件总线（发布订阅）❌️</li><li>webpack与vite的区别</li><li>如何进行Axios配置</li><li>对于一刻短剧的滑动5个就重新刷新的设计原因</li><li>抖音的视频是提前加载，预处理。点赞和收藏是写死的</li><li>一刻短剧的性能优化</li><li>视频的浏览记录历史保存（返回视频有历史播放进度）</li><li>在项目中有没有使用provide与inject</li><li>针对事件监听的节流处理</li><li>你是如何确定当前播放的视频是哪一个的</li><li>防抖的设置</li><li>移动端优先的设计理念❌️</li><li>你部署的CI/CD流程</li><li>4k大屏，但是只能输出1080p，该如何避免缩放失真❌️</li><li>Tailwindcss和普通的css有什么优缺点</li><li>介绍一下项目是如何进行Pinia状态管理的</li><li>localstorage</li><li>主题切换该如何去做</li><li>平时开发有使用什么好用的AI吗</li><li>有了解过我们公司吗</li><li>偏向的公司类型</li><li>直属上级和你在代码上有意见，你该如何解决</li><li>你喜欢什么样的工作环境</li><li>对实习的期待或者希望学习到什么</li><li>个人投递方向全是前端吗</li><li>什么时间入职</li><li>实习多久</li></ul><h3 id="参考答案-1" tabindex="-1"><a class="header-anchor" href="#参考答案-1"><span>参考答案</span></a></h3><p>以下是按「技术类」「项目业务类」「个人求职类」分类的面试参考答案，兼顾实操性、逻辑性和面试表达场景，可根据自身实际经验调整细节：</p><h3 id="技术类问题-突出实操性-核心逻辑" tabindex="-1"><a class="header-anchor" href="#技术类问题-突出实操性-核心逻辑"><span>技术类问题（突出实操性+核心逻辑）</span></a></h3><h5 id="数组去重的方法-常用3种-按场景选择" tabindex="-1"><a class="header-anchor" href="#数组去重的方法-常用3种-按场景选择"><span>数组去重的方法（常用3种，按场景选择）</span></a></h5><ul><li>基础高效版（推荐）：<code>[...new Set(arr)]</code> 或 <code>Array.from(new Set(arr))</code>，利用Set不可重复特性，简洁高效，时间复杂度O(n)，但无法去重对象数组（仅适用于基本类型）。</li><li>兼容低版本/精准控制版：<code>arr.filter((item, index) =&amp;gt; arr.indexOf(item) === index)</code>，利用indexOf返回首次出现索引，筛选唯一元素，可自定义去重规则（如对象数组可加条件）。</li><li>性能优化版（大数据量）：<code>arr.reduce((acc, cur) =&amp;gt; acc.includes(cur) ? acc : [...acc, cur], [])</code>，减少遍历次数，适合需同时处理其他逻辑（如数据转换）的场景。</li></ul><h5 id="promise-all-与-promise-allsettled-的区别" tabindex="-1"><a class="header-anchor" href="#promise-all-与-promise-allsettled-的区别"><span>Promise.all 与 Promise.allSettled 的区别</span></a></h5><table><thead><tr><th>特性</th><th>Promise.all</th><th>Promise.allSettled</th></tr></thead><tbody><tr><td>状态触发</td><td>全部Promise resolved才resolved；任一rejected则立即rejected</td><td>所有Promise完成（无论resolve/reject）后才resolved</td></tr><tr><td>返回结果</td><td>成功：所有结果组成的数组；失败：第一个reject的原因</td><td>每个Promise的结果对象数组（含status和value/reason）</td></tr><tr><td>适用场景</td><td>依赖所有异步结果（如多接口并行获取后合并数据）</td><td>无需依赖所有结果，需知道每个异步的执行状态（如批量请求统计成功/失败数）</td></tr></tbody></table><h5 id="如何设计一个简单的事件总线-发布订阅模式" tabindex="-1"><a class="header-anchor" href="#如何设计一个简单的事件总线-发布订阅模式"><span>如何设计一个简单的事件总线（发布订阅模式）</span></a></h5><p>核心是「事件中心+订阅/发布/取消订阅」三大功能，基于对象存储事件回调：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">class</span> <span class="token class-name">EventBus</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token function">constructor</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">this</span><span class="token punctuation">.</span>events <span class="token operator">=</span> <span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">;</span> <span class="token comment">// 存储事件：{ eventName: [callback1, callback2] }</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line">  <span class="token comment">// 订阅事件</span></span>
<span class="line">  <span class="token function">on</span><span class="token punctuation">(</span><span class="token parameter">eventName<span class="token punctuation">,</span> callback</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token keyword">this</span><span class="token punctuation">.</span>events<span class="token punctuation">[</span>eventName<span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token keyword">this</span><span class="token punctuation">.</span>events<span class="token punctuation">[</span>eventName<span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">this</span><span class="token punctuation">.</span>events<span class="token punctuation">[</span>eventName<span class="token punctuation">]</span><span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span>callback<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line">  <span class="token comment">// 发布事件（传参）</span></span>
<span class="line">  <span class="token function">emit</span><span class="token punctuation">(</span><span class="token parameter">eventName<span class="token punctuation">,</span> <span class="token operator">...</span>args</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">const</span> callbacks <span class="token operator">=</span> <span class="token keyword">this</span><span class="token punctuation">.</span>events<span class="token punctuation">[</span>eventName<span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>callbacks<span class="token punctuation">)</span> callbacks<span class="token punctuation">.</span><span class="token function">forEach</span><span class="token punctuation">(</span><span class="token parameter">cb</span> <span class="token operator">=&gt;</span> <span class="token function">cb</span><span class="token punctuation">(</span><span class="token operator">...</span>args<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line">  <span class="token comment">// 取消订阅（单个回调/全部回调）</span></span>
<span class="line">  <span class="token function">off</span><span class="token punctuation">(</span><span class="token parameter">eventName<span class="token punctuation">,</span> callback</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">const</span> callbacks <span class="token operator">=</span> <span class="token keyword">this</span><span class="token punctuation">.</span>events<span class="token punctuation">[</span>eventName<span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>callbacks<span class="token punctuation">)</span> <span class="token keyword">return</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>callback<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token keyword">this</span><span class="token punctuation">.</span>events<span class="token punctuation">[</span>eventName<span class="token punctuation">]</span> <span class="token operator">=</span> callbacks<span class="token punctuation">.</span><span class="token function">filter</span><span class="token punctuation">(</span><span class="token parameter">cb</span> <span class="token operator">=&gt;</span> cb <span class="token operator">!==</span> callback<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token keyword">delete</span> <span class="token keyword">this</span><span class="token punctuation">.</span>events<span class="token punctuation">[</span>eventName<span class="token punctuation">]</span><span class="token punctuation">;</span> <span class="token comment">// 移除整个事件</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"><span class="token comment">// 使用：const bus = new EventBus(); bus.on(&#39;xxx&#39;, ()=&gt;{}); bus.emit(&#39;xxx&#39;, data);</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>适用场景：非父子组件通信（如Vue2无Pinia时），但需注意避免内存泄漏（组件卸载前off事件）。</p><h5 id="webpack-与-vite-的区别-核心差异" tabindex="-1"><a class="header-anchor" href="#webpack-与-vite-的区别-核心差异"><span>webpack 与 Vite 的区别（核心差异）</span></a></h5><table><thead><tr><th>维度</th><th>webpack</th><th>Vite</th></tr></thead><tbody><tr><td>构建原理</td><td>基于「打包」：先递归解析所有模块，打包成bundle后再启动服务</td><td>基于「原生ES模块（ESM）」：开发时不打包，直接按需加载模块，生产环境用Rollup打包</td></tr><tr><td>热更新（HMR）</td><td>需重新打包更新的模块，大型项目热更新较慢</td><td>只更新修改的模块，无需整体打包，热更新速度极快（毫秒级）</td></tr><tr><td>适用场景</td><td>复杂项目（多入口、复杂依赖、需大量插件定制）、兼容旧浏览器</td><td>现代前端项目（Vue/React/VitePress等）、追求开发效率、无需兼容IE</td></tr><tr><td>启动速度</td><td>随项目体积增大变慢</td><td>启动速度快（不依赖打包）</td></tr><tr><td>插件生态</td><td>生态成熟（插件数量多）</td><td>生态快速发展，兼容部分webpack插件（需适配器）</td></tr></tbody></table><h5 id="如何进行-axios-配置-项目实战版" tabindex="-1"><a class="header-anchor" href="#如何进行-axios-配置-项目实战版"><span>如何进行 Axios 配置（项目实战版）</span></a></h5><p>核心是「基础配置+拦截器+封装复用」，示例：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 1. 基础配置（创建实例）</span></span>
<span class="line"><span class="token keyword">import</span> axios <span class="token keyword">from</span> <span class="token string">&#39;axios&#39;</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> service <span class="token operator">=</span> axios<span class="token punctuation">.</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line">  <span class="token literal-property property">baseURL</span><span class="token operator">:</span> <span class="token keyword">import</span><span class="token punctuation">.</span>meta<span class="token punctuation">.</span>env<span class="token punctuation">.</span><span class="token constant">VITE_API_BASE_URL</span><span class="token punctuation">,</span> <span class="token comment">// 环境变量区分开发/生产</span></span>
<span class="line">  <span class="token literal-property property">timeout</span><span class="token operator">:</span> <span class="token number">5000</span><span class="token punctuation">,</span> <span class="token comment">// 请求超时</span></span>
<span class="line">  <span class="token literal-property property">headers</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token string-property property">&#39;Content-Type&#39;</span><span class="token operator">:</span> <span class="token string">&#39;application/json&#39;</span> <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 2. 请求拦截器（添加Token、统一参数）</span></span>
<span class="line">service<span class="token punctuation">.</span>interceptors<span class="token punctuation">.</span>request<span class="token punctuation">.</span><span class="token function">use</span><span class="token punctuation">(</span></span>
<span class="line">  <span class="token parameter">config</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">const</span> token <span class="token operator">=</span> localStorage<span class="token punctuation">.</span><span class="token function">getItem</span><span class="token punctuation">(</span><span class="token string">&#39;token&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>token<span class="token punctuation">)</span> config<span class="token punctuation">.</span>headers<span class="token punctuation">.</span>Authorization <span class="token operator">=</span> <span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">Bearer </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>token<span class="token interpolation-punctuation punctuation">}</span></span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">return</span> config<span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token parameter">error</span> <span class="token operator">=&gt;</span> Promise<span class="token punctuation">.</span><span class="token function">reject</span><span class="token punctuation">(</span>error<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 3. 响应拦截器（统一错误处理、数据解构）</span></span>
<span class="line">service<span class="token punctuation">.</span>interceptors<span class="token punctuation">.</span>response<span class="token punctuation">.</span><span class="token function">use</span><span class="token punctuation">(</span></span>
<span class="line">  <span class="token parameter">response</span> <span class="token operator">=&gt;</span> response<span class="token punctuation">.</span>data<span class="token punctuation">,</span> <span class="token comment">// 直接返回响应体，简化组件使用</span></span>
<span class="line">  <span class="token parameter">error</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// 统一错误提示（如401token过期、500服务器错误）</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>error<span class="token punctuation">.</span>response<span class="token operator">?.</span>status <span class="token operator">===</span> <span class="token number">401</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">      localStorage<span class="token punctuation">.</span><span class="token function">removeItem</span><span class="token punctuation">(</span><span class="token string">&#39;token&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">      window<span class="token punctuation">.</span>location<span class="token punctuation">.</span>href <span class="token operator">=</span> <span class="token string">&#39;/login&#39;</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    ElMessage<span class="token punctuation">.</span><span class="token function">error</span><span class="token punctuation">(</span>error<span class="token punctuation">.</span>message <span class="token operator">||</span> <span class="token string">&#39;请求失败&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">return</span> Promise<span class="token punctuation">.</span><span class="token function">reject</span><span class="token punctuation">(</span>error<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 4. 封装请求方法（GET/POST）</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">const</span> <span class="token function-variable function">get</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token parameter">url<span class="token punctuation">,</span> params</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> service<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span>url<span class="token punctuation">,</span> <span class="token punctuation">{</span> params <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">const</span> <span class="token function-variable function">post</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token parameter">url<span class="token punctuation">,</span> data</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> service<span class="token punctuation">.</span><span class="token function">post</span><span class="token punctuation">(</span>url<span class="token punctuation">,</span> data<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>扩展：可添加取消请求、请求重试、缓存请求结果等功能。</p><h5 id="节流处理-事件监听场景" tabindex="-1"><a class="header-anchor" href="#节流处理-事件监听场景"><span>节流处理（事件监听场景）</span></a></h5><h5 id="核心逻辑" tabindex="-1"><a class="header-anchor" href="#核心逻辑"><span>核心逻辑</span></a></h5><p>规定时间内只执行一次函数，避免高频事件（滚动、 resize、输入框搜索）触发过多请求/计算。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 通用节流函数（立即执行版）</span></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">throttle</span><span class="token punctuation">(</span><span class="token parameter">fn<span class="token punctuation">,</span> delay <span class="token operator">=</span> <span class="token number">500</span></span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">let</span> lastTime <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> <span class="token comment">// 上一次执行时间</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token parameter"><span class="token operator">...</span>args</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">const</span> now <span class="token operator">=</span> Date<span class="token punctuation">.</span><span class="token function">now</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>now <span class="token operator">-</span> lastTime <span class="token operator">&gt;=</span> delay<span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token comment">// 间隔超过delay才执行</span></span>
<span class="line">      <span class="token function">fn</span><span class="token punctuation">.</span><span class="token function">apply</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">,</span> args<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">      lastTime <span class="token operator">=</span> now<span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 项目使用（如滚动加载）</span></span>
<span class="line">window<span class="token punctuation">.</span><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;scroll&#39;</span><span class="token punctuation">,</span> <span class="token function">throttle</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;滚动触发（500ms一次）&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token comment">// 加载更多逻辑...</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token number">500</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>适用场景：滚动加载、按钮防重复点击（短时间内）、resize事件处理。</p><h5 id="防抖的设置" tabindex="-1"><a class="header-anchor" href="#防抖的设置"><span>防抖的设置</span></a></h5><h5 id="核心逻辑-1" tabindex="-1"><a class="header-anchor" href="#核心逻辑-1"><span>核心逻辑</span></a></h5><p>触发事件后延迟n秒执行，若n秒内再次触发则重新计时，避免高频事件重复执行。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 通用防抖函数（延迟执行版）</span></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">debounce</span><span class="token punctuation">(</span><span class="token parameter">fn<span class="token punctuation">,</span> delay <span class="token operator">=</span> <span class="token number">500</span><span class="token punctuation">,</span> immediate <span class="token operator">=</span> <span class="token boolean">false</span></span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">let</span> timer <span class="token operator">=</span> <span class="token keyword">null</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token parameter"><span class="token operator">...</span>args</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>timer<span class="token punctuation">)</span> <span class="token function">clearTimeout</span><span class="token punctuation">(</span>timer<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 重新触发时清除之前的定时器</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>immediate <span class="token operator">&amp;&amp;</span> <span class="token operator">!</span>timer<span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token comment">// 立即执行版（首次触发直接执行）</span></span>
<span class="line">      <span class="token function">fn</span><span class="token punctuation">.</span><span class="token function">apply</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">,</span> args<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    timer <span class="token operator">=</span> <span class="token function">setTimeout</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token function">fn</span><span class="token punctuation">.</span><span class="token function">apply</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">,</span> args<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">      timer <span class="token operator">=</span> <span class="token keyword">null</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">,</span> delay<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 项目使用（如搜索框输入联想）</span></span>
<span class="line"><span class="token keyword">const</span> searchInput <span class="token operator">=</span> document<span class="token punctuation">.</span><span class="token function">querySelector</span><span class="token punctuation">(</span><span class="token string">&#39;input&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">searchInput<span class="token punctuation">.</span><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;input&#39;</span><span class="token punctuation">,</span> <span class="token function">debounce</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">e</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;搜索请求：&#39;</span><span class="token punctuation">,</span> e<span class="token punctuation">.</span>target<span class="token punctuation">.</span>value<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token comment">// 发送搜索接口...</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token number">300</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>参数说明：<code>immediate: true</code> 适用于按钮提交（避免重复点击且立即响应），<code>false</code> 适用于输入框、搜索联想。</p><h5 id="tailwindcss-和普通-css-的优缺点" tabindex="-1"><a class="header-anchor" href="#tailwindcss-和普通-css-的优缺点"><span>Tailwindcss 和普通 CSS 的优缺点</span></a></h5><table><thead><tr><th>维度</th><th>Tailwindcss</th><th>普通CSS（含SCSS/LESS）</th></tr></thead><tbody><tr><td>优点</td><td>1. 原子化类，开发快速（无需写自定义类）；2. 样式统一，减少命名冲突；3. 支持响应式、主题配置（无需写媒体查询）；4. 生产环境自动 purge 无用样式，体积小</td><td>1. 结构清晰（自定义类名语义化）；2. 灵活度高（复杂样式易实现）；3. 学习成本低（原生语法）；4. 适合复杂组件样式复用（如BEM命名）</td></tr><tr><td>缺点</td><td>1. 类名冗长（如 <code>flex justify-center items-center</code>）；2. 学习成本（需记原子类）；3. 复杂样式需自定义工具类，不如普通CSS直观</td><td>1. 开发效率低（重复写样式）；2. 易产生冗余样式；3. 响应式需写大量媒体查询；4. 多人协作易出现命名冲突</td></tr><tr><td>适用场景</td><td>快速开发、响应式项目、组件库开发（如UI组件）</td><td>复杂设计稿、需高度自定义样式的项目、团队熟悉原生CSS</td></tr></tbody></table><h5 id="项目中如何进行-pinia-状态管理" tabindex="-1"><a class="header-anchor" href="#项目中如何进行-pinia-状态管理"><span>项目中如何进行 Pinia 状态管理</span></a></h5><p>核心是「模块化划分+状态操作规范化」，步骤如下：</p><ol><li><strong>安装配置</strong>：<code>npm install pinia</code>，在入口文件（如main.js）创建Pinia实例并挂载：</li></ol><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> createPinia <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;pinia&#39;</span><span class="token punctuation">;</span></span>
<span class="line">app<span class="token punctuation">.</span><span class="token function">use</span><span class="token punctuation">(</span><span class="token function">createPinia</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><ol start="2"><li><strong>定义模块（Store）</strong>：按业务划分（如user、cart、setting），示例：</li></ol><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// src/stores/user.js</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> defineStore <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;pinia&#39;</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">const</span> useUserStore <span class="token operator">=</span> <span class="token function">defineStore</span><span class="token punctuation">(</span><span class="token string">&#39;user&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token function-variable function">state</span><span class="token operator">:</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token comment">// 状态</span></span>
<span class="line">    <span class="token literal-property property">token</span><span class="token operator">:</span> localStorage<span class="token punctuation">.</span><span class="token function">getItem</span><span class="token punctuation">(</span><span class="token string">&#39;token&#39;</span><span class="token punctuation">)</span> <span class="token operator">||</span> <span class="token string">&#39;&#39;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token literal-property property">userInfo</span><span class="token operator">:</span> <span class="token punctuation">{</span><span class="token punctuation">}</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token literal-property property">getters</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token comment">// 计算属性（缓存）</span></span>
<span class="line">    <span class="token function-variable function">isLogin</span><span class="token operator">:</span> <span class="token punctuation">(</span><span class="token parameter">state</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token operator">!</span><span class="token operator">!</span>state<span class="token punctuation">.</span>token</span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token literal-property property">actions</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token comment">// 异步/同步操作（修改状态）</span></span>
<span class="line">    <span class="token function">setToken</span><span class="token punctuation">(</span><span class="token parameter">newToken</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token keyword">this</span><span class="token punctuation">.</span>token <span class="token operator">=</span> newToken<span class="token punctuation">;</span></span>
<span class="line">      localStorage<span class="token punctuation">.</span><span class="token function">setItem</span><span class="token punctuation">(</span><span class="token string">&#39;token&#39;</span><span class="token punctuation">,</span> newToken<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 持久化</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token keyword">async</span> <span class="token function">fetchUserInfo</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token comment">// 异步请求</span></span>
<span class="line">      <span class="token keyword">const</span> res <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token function">get</span><span class="token punctuation">(</span><span class="token string">&#39;/api/user/info&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">      <span class="token keyword">this</span><span class="token punctuation">.</span>userInfo <span class="token operator">=</span> res<span class="token punctuation">.</span>data<span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ol start="3"><li><strong>组件中使用</strong>：</li></ol><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> useUserStore <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@/stores/user&#39;</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> userStore <span class="token operator">=</span> <span class="token function">useUserStore</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 读取状态</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>userStore<span class="token punctuation">.</span>token<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 修改状态（直接修改/使用$patch批量修改）</span></span>
<span class="line">userStore<span class="token punctuation">.</span><span class="token function">setToken</span><span class="token punctuation">(</span><span class="token string">&#39;xxx&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">userStore<span class="token punctuation">.</span><span class="token function">$patch</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">userInfo</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">name</span><span class="token operator">:</span> <span class="token string">&#39;xxx&#39;</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 异步操作</span></span>
<span class="line">userStore<span class="token punctuation">.</span><span class="token function">fetchUserInfo</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ol start="4"><li><strong>持久化</strong>：简单场景用localStorage/sessionStorage（如上述示例），复杂场景用<code>pinia-plugin-persistedstate</code>插件。</li></ol><h5 id="localstorage-相关-特性-使用场景-注意事项" tabindex="-1"><a class="header-anchor" href="#localstorage-相关-特性-使用场景-注意事项"><span>localStorage 相关（特性+使用场景+注意事项）</span></a></h5><ul><li><strong>核心特性</strong>： <ul><li>存储容量：约5MB；</li><li>持久化：关闭浏览器后数据不丢失（需手动清除）；</li><li>同源限制：同一协议、域名、端口下可访问；</li><li>仅存字符串：需用<code>JSON.stringify()</code>/<code>JSON.parse()</code>处理对象/数组。</li></ul></li><li><strong>使用场景</strong>：存储不敏感的持久化数据（如用户token、主题配置、浏览历史）。</li><li><strong>注意事项</strong>： <ul><li>不能存储敏感数据（如密码，易被XSS攻击窃取）；</li><li>存储大量数据会影响页面加载速度；</li><li>跨域无法访问，需跨域共享数据可使用postMessage+localStorage或后端接口。</li></ul></li></ul><h5 id="主题切换该如何实现" tabindex="-1"><a class="header-anchor" href="#主题切换该如何实现"><span>主题切换该如何实现</span></a></h5><p>核心是「CSS变量+状态管理+持久化」，步骤如下：</p><ol><li><strong>定义主题变量</strong>：在全局CSS中定义不同主题的变量（如light/dark）：</li></ol><div class="language-css line-numbers-mode" data-highlighter="prismjs" data-ext="css"><pre><code class="language-css"><span class="line"><span class="token comment">/* src/assets/css/theme.css */</span></span>
<span class="line"><span class="token selector">:root</span> <span class="token punctuation">{</span> <span class="token comment">/* 默认light主题 */</span></span>
<span class="line">  <span class="token property">--bg-color</span><span class="token punctuation">:</span> #fff<span class="token punctuation">;</span></span>
<span class="line">  <span class="token property">--text-color</span><span class="token punctuation">:</span> #333<span class="token punctuation">;</span></span>
<span class="line">  <span class="token property">--primary-color</span><span class="token punctuation">:</span> #42b983<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"><span class="token selector">.theme-dark</span> <span class="token punctuation">{</span> <span class="token comment">/* dark主题 */</span></span>
<span class="line">  <span class="token property">--bg-color</span><span class="token punctuation">:</span> #121212<span class="token punctuation">;</span></span>
<span class="line">  <span class="token property">--text-color</span><span class="token punctuation">:</span> #eee<span class="token punctuation">;</span></span>
<span class="line">  <span class="token property">--primary-color</span><span class="token punctuation">:</span> #66bb6a<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ol start="2"><li><strong>在Pinia中管理主题状态</strong>：</li></ol><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// src/stores/setting.js</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">const</span> useSettingStore <span class="token operator">=</span> <span class="token function">defineStore</span><span class="token punctuation">(</span><span class="token string">&#39;setting&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token function-variable function">state</span><span class="token operator">:</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line">    <span class="token literal-property property">theme</span><span class="token operator">:</span> localStorage<span class="token punctuation">.</span><span class="token function">getItem</span><span class="token punctuation">(</span><span class="token string">&#39;theme&#39;</span><span class="token punctuation">)</span> <span class="token operator">||</span> <span class="token string">&#39;light&#39;</span> <span class="token comment">// 持久化</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token literal-property property">actions</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token function">toggleTheme</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token keyword">this</span><span class="token punctuation">.</span>theme <span class="token operator">=</span> <span class="token keyword">this</span><span class="token punctuation">.</span>theme <span class="token operator">===</span> <span class="token string">&#39;light&#39;</span> <span class="token operator">?</span> <span class="token string">&#39;dark&#39;</span> <span class="token operator">:</span> <span class="token string">&#39;light&#39;</span><span class="token punctuation">;</span></span>
<span class="line">      localStorage<span class="token punctuation">.</span><span class="token function">setItem</span><span class="token punctuation">(</span><span class="token string">&#39;theme&#39;</span><span class="token punctuation">,</span> <span class="token keyword">this</span><span class="token punctuation">.</span>theme<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">      <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">applyTheme</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 应用主题</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token function">applyTheme</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token comment">// 初始化时应用主题</span></span>
<span class="line">      document<span class="token punctuation">.</span>documentElement<span class="token punctuation">.</span>className <span class="token operator">=</span> <span class="token keyword">this</span><span class="token punctuation">.</span>theme <span class="token operator">===</span> <span class="token string">&#39;dark&#39;</span> <span class="token operator">?</span> <span class="token string">&#39;theme-dark&#39;</span> <span class="token operator">:</span> <span class="token string">&#39;&#39;</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ol start="3"><li><p><strong>组件中使用</strong>：</p><ul><li>样式中使用CSS变量：<code>body { background: var(--bg-color); color: var(--text-color); }</code>；</li><li>切换主题：调用<code>settingStore.toggleTheme()</code>。</li></ul></li><li><p><strong>扩展</strong>：复杂主题（如多配色）可通过动态加载CSS文件实现。</p></li></ol><h5 id="如何确定当前播放的视频是哪一个" tabindex="-1"><a class="header-anchor" href="#如何确定当前播放的视频是哪一个"><span>如何确定当前播放的视频是哪一个</span></a></h5><p>核心是「标识唯一性+状态跟踪」，常用方案：</p><ol><li><strong>给视频元素绑定唯一ID</strong>： <ul><li>每个视频项分配唯一标识（如后端返回的videoId）；</li><li>用Pinia/全局变量存储当前播放的videoId，示例：</li></ul></li></ol><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 视频列表渲染</span></span>
<span class="line"><span class="token operator">&lt;</span>video </span>
<span class="line">  v<span class="token operator">-</span><span class="token keyword">for</span><span class="token operator">=</span><span class="token string">&quot;video in videoList&quot;</span> </span>
<span class="line">  <span class="token operator">:</span>key<span class="token operator">=</span><span class="token string">&quot;video.id&quot;</span></span>
<span class="line">  <span class="token operator">:</span>data<span class="token operator">-</span>id<span class="token operator">=</span><span class="token string">&quot;video.id&quot;</span></span>
<span class="line">  @play<span class="token operator">=</span><span class="token string">&quot;handlePlay(video.id)&quot;</span></span>
<span class="line"><span class="token operator">&gt;</span><span class="token operator">&lt;</span><span class="token operator">/</span>video<span class="token operator">&gt;</span></span>
<span class="line"><span class="token comment">// 记录当前播放视频ID</span></span>
<span class="line"><span class="token keyword">const</span> currentVideoId <span class="token operator">=</span> <span class="token function">ref</span><span class="token punctuation">(</span><span class="token string">&#39;&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> <span class="token function-variable function">handlePlay</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token parameter">videoId</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  currentVideoId<span class="token punctuation">.</span>value <span class="token operator">=</span> videoId<span class="token punctuation">;</span> <span class="token comment">// 存储当前播放ID</span></span>
<span class="line">  <span class="token comment">// 暂停其他视频（可选）</span></span>
<span class="line">  document<span class="token punctuation">.</span><span class="token function">querySelectorAll</span><span class="token punctuation">(</span><span class="token string">&#39;video&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">forEach</span><span class="token punctuation">(</span><span class="token parameter">v</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>v<span class="token punctuation">.</span>dataset<span class="token punctuation">.</span>id <span class="token operator">!==</span> videoId<span class="token punctuation">)</span> v<span class="token punctuation">.</span><span class="token function">pause</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ol start="2"><li><strong>基于DOM元素跟踪</strong>：通过<code>document.activeElement</code>判断是否为视频元素，或用<code>querySelector(&#39;video:playing&#39;)</code>（需结合CSS伪类）。</li><li><strong>框架场景（如Vue）</strong>：用v-model或组件通信传递当前播放状态，避免直接操作DOM。</li></ol><h5 id="视频浏览记录历史保存-含播放进度" tabindex="-1"><a class="header-anchor" href="#视频浏览记录历史保存-含播放进度"><span>视频浏览记录历史保存（含播放进度）</span></a></h5><p>实现方案：「本地存储+接口同步」，步骤如下：</p><ol><li><strong>存储结构设计</strong>：每条记录包含视频ID、标题、封面、播放进度、播放时间，示例：</li></ol><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 单条记录格式</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token literal-property property">videoId</span><span class="token operator">:</span> <span class="token string">&#39;123&#39;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token literal-property property">title</span><span class="token operator">:</span> <span class="token string">&#39;xxx&#39;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token literal-property property">cover</span><span class="token operator">:</span> <span class="token string">&#39;xxx.jpg&#39;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token literal-property property">progress</span><span class="token operator">:</span> <span class="token number">30</span><span class="token punctuation">,</span> <span class="token comment">// 播放进度（秒）</span></span>
<span class="line">  <span class="token literal-property property">lastPlayTime</span><span class="token operator">:</span> <span class="token string">&#39;2024-05-20 10:30&#39;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ol start="2"><li><strong>本地存储（优先）</strong>： <ul><li>用localStorage存储浏览记录（最多保留N条，超出则删除最早的）；</li><li>视频播放时，每3秒或暂停时更新进度：</li></ul></li></ol><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 视频播放事件</span></span>
<span class="line"><span class="token keyword">const</span> video <span class="token operator">=</span> document<span class="token punctuation">.</span><span class="token function">querySelector</span><span class="token punctuation">(</span><span class="token string">&#39;video&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">video<span class="token punctuation">.</span>ontimeupdate <span class="token operator">=</span> <span class="token function">throttle</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">const</span> currentProgress <span class="token operator">=</span> video<span class="token punctuation">.</span>currentTime<span class="token punctuation">;</span></span>
<span class="line">  <span class="token comment">// 更新本地存储中的进度</span></span>
<span class="line">  <span class="token function">updateHistoryProgress</span><span class="token punctuation">(</span>videoId<span class="token punctuation">,</span> currentProgress<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token number">3000</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 节流，避免频繁存储</span></span>
<span class="line">video<span class="token punctuation">.</span><span class="token function-variable function">onpause</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token function">updateHistoryProgress</span><span class="token punctuation">(</span>videoId<span class="token punctuation">,</span> video<span class="token punctuation">.</span>currentTime<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 暂停时强制更新</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ol start="3"><li><strong>接口同步（可选）</strong>：用户登录后，将本地记录同步到后端，实现多设备同步；未登录时仅存储在本地。</li><li><strong>返回视频时恢复进度</strong>：加载视频时，查询本地/后端的历史进度，设置<code>video.currentTime = progress</code>。</li></ol><h5 id="ci-cd-部署流程-前端项目示例" tabindex="-1"><a class="header-anchor" href="#ci-cd-部署流程-前端项目示例"><span>CI/CD 部署流程（前端项目示例）</span></a></h5><p>以「GitHub Actions + 阿里云服务器」为例，核心流程：</p><ol><li><strong>代码管理</strong>：代码托管在GitHub，按分支规范开发（dev开发、main生产）。</li><li><strong>CI（持续集成）</strong>： <ul><li>触发条件：提交代码到dev/main分支时自动触发；</li><li>执行步骤： <ul><li><ol><li>拉取代码；</li></ol></li><li><ol start="2"><li>安装依赖（<code>npm install</code>）；</li></ol></li><li><ol start="3"><li>代码检查（ESLint）；</li></ol></li><li><ol start="4"><li>构建项目（<code>npm run build</code>）；</li></ol></li><li><ol start="5"><li>生成构建产物（dist目录）。</li></ol></li></ul></li></ul></li><li><strong>CD（持续部署）</strong>： <ul><li>开发环境（dev分支）：构建成功后，通过SSH将dist目录上传到测试服务器，自动部署；</li><li>生产环境（main分支）：构建成功后，手动确认部署（或自动部署），上传到生产服务器，替换旧版本。</li></ul></li><li><strong>配置示例（GitHub Actions）</strong>：</li></ol><div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre><code class="language-yaml"><span class="line"><span class="token comment"># .github/workflows/deploy.yml</span></span>
<span class="line"><span class="token key atrule">name</span><span class="token punctuation">:</span> Deploy</span>
<span class="line"><span class="token key atrule">on</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">push</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">branches</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>dev<span class="token punctuation">,</span> main<span class="token punctuation">]</span></span>
<span class="line"><span class="token key atrule">jobs</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">build-and-deploy</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">runs-on</span><span class="token punctuation">:</span> ubuntu<span class="token punctuation">-</span>latest</span>
<span class="line">    <span class="token key atrule">steps</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">uses</span><span class="token punctuation">:</span> actions/checkout@v4</span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Set up Node.js</span>
<span class="line">        <span class="token key atrule">uses</span><span class="token punctuation">:</span> actions/setup<span class="token punctuation">-</span>node@v4</span>
<span class="line">        <span class="token key atrule">with</span><span class="token punctuation">:</span></span>
<span class="line">          <span class="token key atrule">node-version</span><span class="token punctuation">:</span> <span class="token string">&#39;18&#39;</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Install dependencies</span>
<span class="line">        <span class="token key atrule">run</span><span class="token punctuation">:</span> npm install</span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Build</span>
<span class="line">        <span class="token key atrule">run</span><span class="token punctuation">:</span> npm run build</span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Deploy to server</span>
<span class="line">        <span class="token key atrule">uses</span><span class="token punctuation">:</span> easingthemes/ssh<span class="token punctuation">-</span>deploy@main</span>
<span class="line">        <span class="token key atrule">env</span><span class="token punctuation">:</span></span>
<span class="line">          <span class="token key atrule">SSH_PRIVATE_KEY</span><span class="token punctuation">:</span> $<span class="token punctuation">{</span><span class="token punctuation">{</span> secrets.SSH_PRIVATE_KEY <span class="token punctuation">}</span><span class="token punctuation">}</span> <span class="token comment"># 服务器私钥（GitHub Secrets存储）</span></span>
<span class="line">          <span class="token key atrule">ARGS</span><span class="token punctuation">:</span> <span class="token string">&quot;-rltgoDzvO --delete&quot;</span></span>
<span class="line">          <span class="token key atrule">SOURCE</span><span class="token punctuation">:</span> <span class="token string">&quot;dist/&quot;</span> <span class="token comment"># 构建产物目录</span></span>
<span class="line">          <span class="token key atrule">REMOTE_HOST</span><span class="token punctuation">:</span> $<span class="token punctuation">{</span><span class="token punctuation">{</span> secrets.REMOTE_HOST <span class="token punctuation">}</span><span class="token punctuation">}</span> <span class="token comment"># 服务器IP</span></span>
<span class="line">          <span class="token key atrule">REMOTE_USER</span><span class="token punctuation">:</span> $<span class="token punctuation">{</span><span class="token punctuation">{</span> secrets.REMOTE_USER <span class="token punctuation">}</span><span class="token punctuation">}</span> <span class="token comment"># 服务器用户名</span></span>
<span class="line">          <span class="token key atrule">TARGET</span><span class="token punctuation">:</span> <span class="token string">&quot;/var/www/xxx&quot;</span> <span class="token comment"># 服务器部署目录</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ol start="5"><li><strong>扩展</strong>：可集成自动化测试（Jest、Cypress），测试通过后再部署。</li></ol><h5 id="provide-与-inject-使用场景" tabindex="-1"><a class="header-anchor" href="#provide-与-inject-使用场景"><span>provide 与 inject 使用场景</span></a></h5><ul><li><strong>核心作用</strong>：Vue中跨层级组件通信（父组件向子孙组件传递数据/方法，无需逐层props传递）。</li><li><strong>使用方式</strong>：</li></ul><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 父组件（provide提供数据）</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> provide <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;vue&#39;</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token function">provide</span><span class="token punctuation">(</span><span class="token string">&#39;theme&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;dark&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 第一个参数是key，第二个是值（可传对象、方法）</span></span>
<span class="line"><span class="token function">provide</span><span class="token punctuation">(</span><span class="token string">&#39;changeTheme&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token parameter">newTheme</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span> <span class="token comment">/* 方法 */</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 子孙组件（inject接收数据）</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> inject <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;vue&#39;</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> theme <span class="token operator">=</span> <span class="token function">inject</span><span class="token punctuation">(</span><span class="token string">&#39;theme&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;light&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 第二个参数是默认值</span></span>
<span class="line"><span class="token keyword">const</span> changeTheme <span class="token operator">=</span> <span class="token function">inject</span><span class="token punctuation">(</span><span class="token string">&#39;changeTheme&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><strong>项目应用场景</strong>： <ul><li>全局配置（如主题、语言、权限）；</li><li>组件库开发（如ElMessageBox、ElNotification，通过provide/inject传递全局配置）；</li></ul></li><li><strong>注意事项</strong>： <ul><li>数据是响应式的（若传递的是响应式对象/refs）；</li><li>避免滥用，跨层级通信优先用Pinia，provide/inject适合简单场景。</li></ul></li></ul><h5 id="移动端优先的设计理念" tabindex="-1"><a class="header-anchor" href="#移动端优先的设计理念"><span>移动端优先的设计理念</span></a></h5><ul><li><strong>核心定义</strong>：先设计移动端界面（小屏幕），再基于大屏设备（平板、PC）进行适配扩展，而非反过来。</li><li><strong>实现方式</strong>： <ul><li>响应式布局：用媒体查询（<code>@media (min-width: 768px)</code>）适配大屏；</li><li>弹性布局：flex/grid布局，适应不同屏幕宽度；</li><li>相对单位：用rem/vw/vh（如1rem=100px，通过html字体大小适配），避免固定px；</li><li>触控友好：按钮尺寸≥44px×44px，间距合理，避免密集操作。</li></ul></li><li><strong>优势</strong>： <ul><li>适配更精准，避免大屏适配后移动端体验差；</li><li>聚焦核心功能（移动端屏幕有限，优先保留核心功能）；</li><li>符合移动设备使用场景增长趋势。</li></ul></li></ul><h5 id="_4k大屏仅输出1080p-如何避免缩放失真" tabindex="-1"><a class="header-anchor" href="#_4k大屏仅输出1080p-如何避免缩放失真"><span>4K大屏仅输出1080p，如何避免缩放失真</span></a></h5><ul><li><strong>核心思路</strong>：让页面按「物理像素」渲染，避免浏览器自动缩放。</li><li><strong>实现方案</strong>： <ol><li><strong>设置meta标签</strong>：确保viewport不缩放，适配设备宽度：</li></ol></li></ul><div class="language-html line-numbers-mode" data-highlighter="prismjs" data-ext="html"><pre><code class="language-html"><span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>meta</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>viewport<span class="token punctuation">&quot;</span></span> <span class="token attr-name">content</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ol start="2"><li><strong>使用相对单位</strong>：用vw/vh（1vw=屏幕宽度的1%）或rem，基于屏幕宽度动态计算元素尺寸，而非固定px。</li><li><strong>图片/资源适配</strong>：使用高分辨率图片（如2x图），通过<code>image-set</code>自动选择适配图片：</li></ol><div class="language-css line-numbers-mode" data-highlighter="prismjs" data-ext="css"><pre><code class="language-css"><span class="line"><span class="token selector">.img</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">background-image</span><span class="token punctuation">:</span> <span class="token function">image-set</span><span class="token punctuation">(</span></span>
<span class="line">    <span class="token url"><span class="token function">url</span><span class="token punctuation">(</span><span class="token string url">&#39;img-1080p.jpg&#39;</span><span class="token punctuation">)</span></span> 1x<span class="token punctuation">,</span></span>
<span class="line">    <span class="token url"><span class="token function">url</span><span class="token punctuation">(</span><span class="token string url">&#39;img-4k.jpg&#39;</span><span class="token punctuation">)</span></span> 2x</span>
<span class="line">  <span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ol start="4"><li><strong>CSS媒体查询适配</strong>：针对4K屏幕（如<code>min-width: 3840px</code>）单独优化布局，避免元素被过度拉伸。</li><li><strong>框架层面适配</strong>：如Vue项目可使用<code>postcss-px-to-viewport</code>插件，自动将px转换为vw。</li></ol><h3 id="项目业务类问题-结合业务场景-技术选型原因" tabindex="-1"><a class="header-anchor" href="#项目业务类问题-结合业务场景-技术选型原因"><span>项目业务类问题（结合业务场景+技术选型原因）</span></a></h3><h5 id="一刻短剧-滑动5个就重新刷新-的设计原因" tabindex="-1"><a class="header-anchor" href="#一刻短剧-滑动5个就重新刷新-的设计原因"><span>一刻短剧&quot;滑动5个就重新刷新&quot;的设计原因</span></a></h5><p>核心是「性能优化+用户体验+业务需求」：</p><ul><li><strong>性能优化</strong>：避免一次性加载过多视频（每个视频含视频文件、封面、文案），导致内存占用过高、页面卡顿，滑动5个刷新可分批加载，降低首屏加载压力。</li><li><strong>用户体验</strong>：用户连续滑动5个后，大概率需要新内容，提前刷新可避免后续滑动时出现&quot;空白加载&quot;，保证流畅性。</li><li><strong>业务需求</strong>：短剧内容多为连载/批量更新，分批刷新可优先展示最新/热门内容，同时减少接口请求频率（批量请求5个 vs 每次滑动请求1个）。</li><li><strong>扩展</strong>：可结合&quot;预加载&quot;（滑动到第3个时就请求下一批），进一步提升体验。</li></ul><h5 id="抖音视频-提前加载、预处理-点赞收藏-写死-的设计逻辑" tabindex="-1"><a class="header-anchor" href="#抖音视频-提前加载、预处理-点赞收藏-写死-的设计逻辑"><span>抖音视频&quot;提前加载、预处理&quot;，点赞收藏&quot;写死&quot;的设计逻辑</span></a></h5><ul><li><strong>提前加载+预处理</strong>： <ul><li>原因：视频播放需低延迟，提前加载（如用户当前播放第1个时，预加载第2、3个）可避免播放时缓冲；</li><li>预处理：对视频进行转码（适配不同网络/设备）、压缩（减少文件大小）、缓存（本地存储近期播放的视频），提升加载速度。</li></ul></li><li><strong>点赞收藏&quot;写死&quot;（实际是本地缓存+异步同步）</strong>： <ul><li>设计逻辑：用户点击点赞/收藏时，先本地更新状态（如点赞按钮立即变红），再异步调用接口同步到后端；</li><li>优势：避免接口请求延迟导致的&quot;点击后无反应&quot;，提升交互流畅性；即使网络波动，本地状态也能保持，后续网络恢复后自动同步。</li></ul></li></ul><h5 id="一刻短剧的性能优化方案-前端层面" tabindex="-1"><a class="header-anchor" href="#一刻短剧的性能优化方案-前端层面"><span>一刻短剧的性能优化方案（前端层面）</span></a></h5><ul><li><strong>资源优化</strong>： <ul><li>视频优化：转码为HLS格式（支持分片加载）、根据网络状况切换清晰度（4G加载720p，WiFi加载1080p）；</li><li>图片优化：封面图使用WebP格式（压缩比高）、懒加载（<code>loading=&quot;lazy&quot;</code>）、缩略图预览。</li></ul></li><li><strong>渲染优化</strong>： <ul><li>列表虚拟化：使用<code>vue-virtual-scroller</code>等插件，只渲染可视区域内的视频项，避免大量DOM节点导致卡顿；</li><li>减少重绘重排：视频容器尺寸固定，避免滑动时DOM结构变化；使用CSS3硬件加速（<code>transform: translateZ(0)</code>）。</li></ul></li><li><strong>接口优化</strong>： <ul><li>批量请求：滑动时批量请求视频列表，减少接口调用次数；</li><li>缓存策略：本地缓存已请求的视频列表、用户操作（点赞/收藏），避免重复请求；</li><li>接口防抖：搜索、筛选时添加防抖，避免高频请求。</li></ul></li><li><strong>其他优化</strong>： <ul><li>懒加载非核心组件：如评论区、分享功能，滑动到对应区域再加载；</li><li>内存释放：用户离开视频页面时，销毁视频实例、清除定时器，避免内存泄漏。</li></ul></li></ul><h3 id="个人求职类问题-真诚-贴合岗位-展现适配性" tabindex="-1"><a class="header-anchor" href="#个人求职类问题-真诚-贴合岗位-展现适配性"><span>个人求职类问题（真诚+贴合岗位+展现适配性）</span></a></h3><h5 id="有了解过我们公司吗" tabindex="-1"><a class="header-anchor" href="#有了解过我们公司吗"><span>有了解过我们公司吗？</span></a></h5><p>参考回答： &quot;了解过。贵公司是[行业领域，如&quot;国内领先的短剧平台&quot;/&quot;专注于前端工程化解决方案的科技公司&quot;]，核心业务包括[具体业务，如&quot;一刻短剧APP的开发与运营&quot;/&quot;企业级前端框架定制&quot;]，之前关注到贵公司推出的[产品/技术，如&quot;XX短剧系列&quot;/&quot;XX前端组件库&quot;]在行业内口碑很好，技术栈上以[前端技术，如Vue、Vite、Pinia]为主，和我目前的技术方向非常契合。另外，贵公司在[团队文化/行业地位，如&quot;重视技术创新&quot;/&quot;快速发展的创业氛围&quot;]方面的特点，也是我非常认可的，所以很希望能加入团队。&quot;</p><h5 id="偏向的公司类型" tabindex="-1"><a class="header-anchor" href="#偏向的公司类型"><span>偏向的公司类型？</span></a></h5><p>参考回答： &quot;我更偏向「技术驱动+重视成长」的公司。一方面，希望公司有清晰的技术栈和工程化规范，能让我在实际项目中积累更专业的开发经验；另一方面，希望团队有良好的技术分享氛围，能和优秀的同事一起交流学习，不断提升自己的技术能力。贵公司的[业务/技术方向]正好符合我的期待，无论是项目复杂度还是技术迭代速度，都能让我快速成长。&quot;</p><h5 id="直属上级和你在代码上有意见分歧-你该如何解决" tabindex="-1"><a class="header-anchor" href="#直属上级和你在代码上有意见分歧-你该如何解决"><span>直属上级和你在代码上有意见分歧，你该如何解决？</span></a></h5><p>参考回答： &quot;首先，我会先认真倾听上级的想法，了解他的核心诉求和考虑角度（比如性能、可维护性、业务兼容性），避免因为信息偏差导致分歧。然后，我会客观陈述自己的思路，比如代码的设计逻辑、技术选型的原因、可能带来的优势（如开发效率、后续扩展性），并拿出具体的示例或数据支持（如性能测试结果、类似项目案例）。如果还是无法达成共识，我会建议先小范围验证两种方案的可行性（比如写demo测试），基于实际效果做决策，而不是固执己见。最终的目标是保证代码质量和业务目标的实现，所以我会以理性、开放的态度沟通，尊重团队的最终决定。&quot;</p><h5 id="你喜欢什么样的工作环境" tabindex="-1"><a class="header-anchor" href="#你喜欢什么样的工作环境"><span>你喜欢什么样的工作环境？</span></a></h5><p>参考回答： &quot;我喜欢「开放协作+高效务实」的工作环境。第一，团队内部沟通顺畅，遇到问题可以随时和同事、上级交流，没有层级壁垒；第二，大家都以结果为导向，注重效率，不搞形式主义；第三，有学习和成长的空间，比如定期的技术分享、项目复盘，能让我不断积累经验。另外，我也很看重工作和生活的平衡，这样才能保持持续的工作热情。&quot;</p><h5 id="对实习的期待或者希望学习到什么" tabindex="-1"><a class="header-anchor" href="#对实习的期待或者希望学习到什么"><span>对实习的期待或者希望学习到什么？</span></a></h5><p>参考回答： &quot;首先，希望能深入参与实际项目的开发，将学校学到的理论知识转化为实操能力，尤其是在[前端技术方向，如Vue框架深入、工程化实践、性能优化]方面，积累真实项目的经验；其次，希望能学习到公司的开发规范和流程，比如代码评审、CI/CD部署、团队协作模式，培养专业的开发习惯；最后，希望能在前辈的指导下，提升解决问题的能力，比如遇到技术难题时的排查思路、业务需求的理解和转化能力。同时，我也会积极贡献自己的力量，认真完成分配的任务，为团队创造价值。&quot;</p><h5 id="个人投递方向全是前端吗" tabindex="-1"><a class="header-anchor" href="#个人投递方向全是前端吗"><span>个人投递方向全是前端吗？</span></a></h5><p>参考回答： &quot;是的，我一直专注于前端开发方向。从学习阶段开始，我就系统学习了HTML、CSS、JavaScript、Vue等核心技术，也做过[个人项目/课程项目，如&quot;博客系统&quot;/&quot;短视频播放器&quot;]等前端相关项目，积累了一定的实操经验。我对前端开发的兴趣很浓厚，尤其是在用户交互体验、工程化优化方面，希望能一直深耕这个领域，所以投递的全部是前端相关岗位。&quot;</p><h5 id="什么时间入职" tabindex="-1"><a class="header-anchor" href="#什么时间入职"><span>什么时间入职？</span></a></h5><p>参考回答： &quot;我目前是[学生身份，如&quot;大三学生&quot;]，课程安排比较灵活，只要拿到offer，我可以在[具体时间，如&quot;1-2周内&quot;/&quot;暑假期间&quot;]入职，并且能保证[实习时长，如&quot;3个月以上&quot;]的全职实习时间，期间会合理协调学业和工作，确保不影响实习任务的完成。&quot;</p><h5 id="实习多久" tabindex="-1"><a class="header-anchor" href="#实习多久"><span>实习多久？</span></a></h5><p>参考回答： &quot;我计划实习[3-6个月]，如果期间双方合作愉快，并且学校课程允许，我也非常愿意延长实习时间。我希望能有足够的时间深入参与项目，不仅完成基础任务，还能在后续的工作中承担更多责任，真正学到东西，同时也为团队带来持续的价值。&quot;</p><h5 id="平时开发有使用什么好用的ai吗" tabindex="-1"><a class="header-anchor" href="#平时开发有使用什么好用的ai吗"><span>平时开发有使用什么好用的AI吗？</span></a></h5><p>参考回答： &quot;我常用的AI工具主要是辅助开发效率的，比如：</p><ul><li>GitHub Copilot：写代码时提供自动补全、语法提示，尤其是复杂逻辑或不熟悉的API，能节省查文档的时间；</li><li>ChatGPT：遇到技术难题（如bug排查、语法疑问）时，会用来辅助分析思路，但不会直接复制代码，而是理解后结合自己的需求修改；</li><li>CodeLlama：偶尔用来优化代码结构、生成单元测试；</li><li>Figma AI：如果涉及简单的UI设计（如项目原型），会用它辅助生成设计稿，提升协作效率。</li></ul><p>我认为AI是很好的辅助工具，但核心还是自己的技术能力，所以会合理利用AI提升效率，同时注重理解底层逻辑，避免过度依赖。&quot;</p><hr><h3 id="分割线" tabindex="-1"><a class="header-anchor" href="#分割线"><span>分割线</span></a></h3><p>如果需要针对某个问题的答案进行细化（如补充具体项目案例、调整表达风格），或者想模拟面试场景进行问答演练，欢迎告诉我，我可以帮你进一步优化！</p><h3 id="复盘反思-1" tabindex="-1"><a class="header-anchor" href="#复盘反思-1"><span>复盘反思</span></a></h3><p>首先，不要眼睛到处看，不要乱动身体，不要摇头晃脑，看着很不礼貌，端坐看着屏幕。本次的面试说是技术面是最后一次，也就是我的全部面试都已经结束了，我个人感觉很有希望啊！😋😋😋</p><p>&gt;11/27/25 不是，都一整天了，怎么还不给我发offer啊？我还不够格吗？</p>`,185)])])}const i=s(e,[["render",l]]),u=JSON.parse('{"path":"/notes/obsidian/%E5%89%8D%E7%AB%AF/%E9%9D%A2%E8%AF%95/%E9%9D%A2%E7%BB%8F/1%E7%A3%90%E6%9D%BE%E8%B5%84%E4%BA%A7-%E5%89%8D%E7%AB%AF%E5%AE%9E%E4%B9%A0-%E4%B8%80%E9%9D%A2.html","title":"1磐松资产-前端实习-一面","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"notes/obsidian/前端/面试/面经/1磐松资产-前端实习-一面.md"}');export{i as comp,u as data};
